// The pull program as an sBPF v3 ELF: program-extended's build, doppler/doppler-pull.so and
// doppler/doppler-pull-memcpy.so, with the admin key, the copy and the sizes patched into the listing
// it starts with, and the admin and the program id patched into `.rodata`. doppler/tests/vectors.json
// pins the digest of every result.

import { HEADER, MEMCPY_THRESHOLD, padded } from './program.js';

/** What the admin signs for a pull, before the program id and the update. */
export const DOMAIN = new Uint8Array([0xff, ...new TextEncoder().encode('doppler:pull:v1')]);

/**
 * A limit for the pull path, not its exact cost: brine-ed25519's Barrett reduction takes data-dependent
 * corrections, measured from 4,958 to 5,012 over 1,200 signatures plus the hash's `max(10, len / 2)` on the
 * update slice, so the limit carries 18 units over the largest seen. Pinned by doppler/tests/sweep.rs.
 */
export function pullCu(payloadSize: number): number {
  return 5_030 + Math.max(10, Math.floor((HEADER + padded(payloadSize)) / 2));
}

const fromBase64 = (text: string) => Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
/** program-extended: one copy pair in the listing, then `pull`. */
const INLINE = fromBase64('');
/** program-extended with the `memcpy` feature. */
const MEMCPY = fromBase64('');
/** The file offset of slot 0: `.rodata` at 0xe8, mapped at 0, precedes the code, mapped at 2^32. */
const CODE = 0x140;
/** The code's program header: `p_filesz` and `p_memsz` grow with the pairs. */
const LOAD = 0x40 + 56;
/** The `lddw` slots holding the admin key: the low word at slot + 4, the high word at slot + 12. */
const ADMIN_SLOTS = [3, 7, 11, 15];
/** `jne r3, 0x1ff, detached`: the offset grows with the pairs. */
const DETACHED_SLOT = 1;
/** Inline: `ldxdw r4, [r2+8]` and `stxdw [r1+0x28c8], r4`. */
const PAIR_SLOT = 23;
/** Memcpy: `mov64 r3, len`. */
const LEN_SLOT = 23;
const FEED_DATA = 0x28c0;
/** `.rodata`: the admin, then the program id. */
const ADMIN = 0xf0;
const ID = 0x110;

export function generatePull(admin: Uint8Array, program: Uint8Array, payloadSize: number): Uint8Array {
  if (admin.length !== 32 || program.length !== 32) throw new RangeError('a key is 32 bytes');
  if (!Number.isInteger(payloadSize) || payloadSize < 1) throw new RangeError('a payload needs at least one byte');
  const size = padded(payloadSize);
  const c = size / 8;
  const slot = (i: number) => CODE + 8 * i;
  let p: Uint8Array;
  let view: DataView;
  if (c < MEMCPY_THRESHOLD) {
    p = new Uint8Array(INLINE.length + 16 * (c - 1));
    view = new DataView(p.buffer);
    p.set(INLINE.subarray(0, slot(PAIR_SLOT)));
    for (let i = 0; i < c; i++) {
      const at = slot(PAIR_SLOT + 2 * i);
      p.set(INLINE.subarray(slot(PAIR_SLOT), slot(PAIR_SLOT + 2)), at);
      view.setInt16(at + 2, HEADER + 8 * i, true);
      view.setInt16(at + 10, FEED_DATA + HEADER + 8 * i, true);
    }
    p.set(INLINE.subarray(slot(PAIR_SLOT + 2)), slot(PAIR_SLOT + 2 * c));
    view.setBigUint64(LOAD + 0x20, BigInt(p.length - CODE), true);
    view.setBigUint64(LOAD + 0x28, BigInt(p.length - CODE), true);
    const jne = slot(DETACHED_SLOT) + 2;
    view.setInt16(jne, view.getInt16(jne, true) + 2 * (c - 1), true);
  } else {
    p = MEMCPY.slice();
    view = new DataView(p.buffer);
    view.setInt32(slot(LEN_SLOT) + 4, HEADER + size, true);
  }
  const key = new DataView(admin.buffer, admin.byteOffset, 32);
  ADMIN_SLOTS.forEach((at, i) => {
    view.setInt32(slot(at) + 4, key.getInt32(8 * i, true), true);
    view.setInt32(slot(at) + 12, key.getInt32(8 * i + 4, true), true);
  });
  p.set(admin, ADMIN);
  p.set(program, ID);
  return p;
}
